-- ==== functions (04_functions_views.sql) ====
CREATE OR REPLACE FUNCTION public.create_student_link_code()
 RETURNS TABLE(code text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE student_role TEXT; raw_code TEXT; code_expiry TIMESTAMPTZ := now() + interval '15 minutes';
BEGIN
  SELECT role INTO student_role FROM public.profiles WHERE id = auth.uid();
  IF student_role IS DISTINCT FROM 'student' THEN RAISE EXCEPTION 'only student accounts can create guardian link codes'; END IF;
  UPDATE public.student_link_codes SET revoked_at = now() WHERE student_profile_id = auth.uid() AND redeemed_at IS NULL AND revoked_at IS NULL;
  raw_code := upper(encode(gen_random_bytes(5), 'hex'));
  INSERT INTO public.student_link_codes(student_profile_id, code_hash, expires_at) VALUES (auth.uid(), encode(digest(raw_code, 'sha256'), 'hex'), code_expiry);
  RETURN QUERY SELECT raw_code, code_expiry;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_teacher_feedback_summary(teacher_uuid text)
 RETURNS TABLE(total_decisions bigint, feedback_given bigint, helpful_count bigint, not_helpful_count bigint, feedback_rate double precision)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    COUNT(*)::BIGINT as total_decisions,
    COUNT(teacher_feedback)::BIGINT as feedback_given,
    COUNT(*) FILTER (WHERE teacher_feedback = 'helpful')::BIGINT as helpful_count,
    COUNT(*) FILTER (WHERE teacher_feedback = 'not_helpful')::BIGINT as not_helpful_count,
    (COUNT(teacher_feedback)::FLOAT / NULLIF(COUNT(*), 0)) as feedback_rate
  FROM ai_decisions
  WHERE teacher_id = teacher_uuid;
END;
$function$


CREATE OR REPLACE FUNCTION public.get_top_rules(limit_count integer DEFAULT 10)
 RETURNS TABLE(rule_id text, rule_name text, success_rate double precision, times_applied integer, confidence double precision)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    lr.rule_id,
    lr.rule_name,
    (lr.times_helpful::FLOAT / NULLIF(lr.times_applied, 0)) as success_rate,
    lr.times_applied,
    lr.confidence
  FROM learned_rules lr
  WHERE lr.status = 'active'
    AND lr.times_applied > 10 -- Minimum sample size
  ORDER BY (lr.times_helpful::FLOAT / NULLIF(lr.times_applied, 0)) DESC
  LIMIT limit_count;
END;
$function$


CREATE OR REPLACE FUNCTION public.redeem_student_link_code(p_code text)
 RETURNS TABLE(student_profile_id uuid, linked_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE parent_role TEXT; code_row public.student_link_codes%ROWTYPE; normalized_code TEXT := upper(regexp_replace(coalesce(p_code, ''), '[^A-Z0-9]', '', 'g'));
BEGIN
  SELECT role INTO parent_role FROM public.profiles WHERE id = auth.uid();
  IF parent_role IS DISTINCT FROM 'parent' THEN RAISE EXCEPTION 'only parent accounts can redeem guardian link codes'; END IF;
  IF length(normalized_code) < 12 THEN RAISE EXCEPTION 'invalid guardian link code'; END IF;
  SELECT * INTO code_row FROM public.student_link_codes WHERE code_hash = encode(digest(normalized_code, 'sha256'), 'hex') AND redeemed_at IS NULL AND revoked_at IS NULL AND expires_at > now() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'invalid, expired, or already used guardian link code'; END IF;
  INSERT INTO public.parent_student_links(parent_profile_id, student_profile_id, status) VALUES (auth.uid(), code_row.student_profile_id, 'active') ON CONFLICT (parent_profile_id, student_profile_id) DO UPDATE SET status = 'active', revoked_at = NULL, linked_at = now();
  UPDATE public.profiles SET children_ids = CASE WHEN code_row.student_profile_id = ANY(children_ids) THEN children_ids ELSE array_append(children_ids, code_row.student_profile_id) END, updated_at = now() WHERE id = auth.uid();
  UPDATE public.student_link_codes SET redeemed_at = now() WHERE id = code_row.id;
  RETURN QUERY SELECT code_row.student_profile_id, now();
END;
$function$


CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$


CREATE OR REPLACE FUNCTION public.syncsenta_is_head_for(p_student_id text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$ SELECT private.syncsenta_is_head_for(p_student_id); $function$


CREATE OR REPLACE FUNCTION public.syncsenta_is_head_of(p_subject uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$ SELECT private.syncsenta_is_head_of(p_subject); $function$


