 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$ SELECT private.syncsenta_is_parent_for(p_student_id); $function$


CREATE OR REPLACE FUNCTION public.syncsenta_is_parent_of(p_subject uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$ SELECT private.syncsenta_is_parent_of(p_subject); $function$


CREATE OR REPLACE FUNCTION public.syncsenta_is_student_for(p_student_id text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  SELECT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND p.role='student' AND (p.id::text=p_student_id OR p.student_id=p_student_id));
$function$


CREATE OR REPLACE FUNCTION public.syncsenta_is_teacher_for(p_student_id text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  SELECT EXISTS (SELECT 1 FROM public.teacher_student_assignments a JOIN public.profiles p ON p.id=a.teacher_id JOIN public.students s ON s.id=a.student_id WHERE p.id=auth.uid() AND p.role='teacher' AND a.status='active' AND (s.id::text=p_student_id OR s.student_id=p_student_id));
$function$


CREATE OR REPLACE FUNCTION public.syncsenta_touch_school_directory()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $function$

-- ==== triggers (02_constraints.sql) ====
CREATE TRIGGER school_classes_updated_at BEFORE UPDATE ON public.school_classes FOR EACH ROW EXECUTE FUNCTION syncsenta_touch_school_directory();
CREATE TRIGGER schools_updated_at BEFORE UPDATE ON public.schools FOR EACH ROW EXECUTE FUNCTION syncsenta_touch_school_directory();

